import { sql } from "drizzle-orm";
import { timestamp, uuid } from "drizzle-orm/pg-core";

/** UUID primary key (generated by Postgres: gen_random_uuid()). Used by every table. */
export const pk = () => uuid("id").primaryKey().defaultRandom();

/** created_at / updated_at on every table (updated_at is refreshed by Drizzle on update). */
export const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
};

/** Soft-delete marker for content tables. NULL = live. */
export const softDelete = {
  deletedAt: timestamp("deleted_at", { withTimezone: true }),
};

/** timestamptz column helper. */
export const tstz = (name: string) => timestamp(name, { withTimezone: true });

export { sql };
